public class Test {
    static int x = 1;
    static int compute() {
        int y = 10;
        try {
            x++;
            return y;
        } finally {
            y = 20;
            x++;
        }
    }
    public static void main(String[] args) {
        int r = compute();
        System.out.println(r + " " + x);
    }
